#[path = "solution.rs"]
mod solution;

use solution::{append_and_measure, countdown, first_word, is_below_five, tuple_fields};

#[test]
fn tuple_fields_borrows_and_preserves_the_tuple() {
    let value = (-7, true, String::from("hello"));
    let string_address = value.2.as_ptr();
    let fields = tuple_fields(&value);
    assert_eq!(fields, (-7, true, "hello"));
    assert_eq!(fields.2.as_ptr(), string_address);
    assert_eq!(value, (-7, true, String::from("hello")));
}

#[test]
fn below_five_is_strict() {
    assert!(is_below_five(i32::MIN));
    assert!(is_below_five(4));
    assert!(!is_below_five(5));
    assert!(!is_below_five(i32::MAX));
}

#[test]
fn countdown_handles_zero_and_normal_starts() {
    assert_eq!(countdown(0), vec!["LIFTOFF!".to_string()]);
    assert_eq!(countdown(3), vec![
        "3!".to_string(),
        "2!".to_string(),
        "1!".to_string(),
        "LIFTOFF!".to_string(),
    ]);
}

#[test]
fn append_and_measure_appends_once_and_counts_utf8_bytes() {
    let (text, length) = append_and_measure(String::from("café"), "🚀");
    assert_eq!(text, "café🚀");
    assert_eq!(length, "café🚀".len());

    let (unchanged, length) = append_and_measure(String::from("abc"), "");
    assert_eq!(unchanged, "abc");
    assert_eq!(length, 3);
}

#[test]
fn first_word_skips_unicode_whitespace_and_returns_original_slice() {
    let text = "\u{2003}\talpha-beta\u{00a0}gamma";
    let word = first_word(text);
    assert_eq!(word, "alpha-beta");
    let offset = word.as_ptr() as usize - text.as_ptr() as usize;
    assert_eq!(offset, "\u{2003}\t".len());

    assert_eq!(first_word("single"), "single");
    assert_eq!(first_word(""), "");
    assert_eq!(first_word(" \n\u{2003}\t"), "");
}

